class Policy:
    # Use cheap scores to break ties and require a minimum improvement margin
    # to avoid committing noise when the held-out estimates are close.
    def accept(self, ctx):
        base = MergeContext.rate(ctx.base_counts)
        cand = MergeContext.rate(ctx.cand_counts)
        delta = cand - base

        # If candidate clearly beats base on held-out, commit
        if delta > 0.02:
            return AcceptDecision(True, "committed", "", 1.0, delta)

        # If held-out is close, use cheap scores as a tiebreaker
        # (cheap is a float, not a pair)
        if abs(delta) <= 0.02 and ctx.cand_cheap > ctx.base_cheap:
            return AcceptDecision(True, "committed-cheap-tiebreak", 
                                 "held-out close, cheap favors cand", 0.6, delta)

        return AcceptDecision(False, "below-threshold",
                              "held-out did not improve enough", 0.0, delta)
```

